cd /root/nanobot-src && python3 -c "
import re, os

# Collect all callback_data values from settings.py
settings_cbs = set()
with open('nanobot/channels/telegram/commands/settings.py') as f:
    for m in re.finditer(r'callback_data=\"([^\"]+)\"', f.read()):
        settings_cbs.add(m.group(1))

# Collect all handled patterns from callbacks/
handled_exact = set()
handled_prefixes = set()
for root, dirs, files in os.walk('nanobot/channels/telegram/callbacks'):
    for fn in files:
        if not fn.endswith('.py'): continue
        with open(os.path.join(root, fn)) as f:
            content = f.read()
        # data == 'xxx' or data in ('xxx', 'yyy')
        for m in re.finditer(r'data\s*(?:==|in)\s*[(]?\"([^\"]+)\"', content):
            handled_exact.add(m.group(1))
        # data.startswith('xxx')
        for m in re.finditer(r'data\.startswith\(\"([^\"]+)\"', content):
            handled_prefixes.add(m.group(1))

print('=== Callbacks generated in settings.py ===')
for cb in sorted(settings_cbs):
    print(f'  {cb}')

print()
print('=== UNHANDLED callbacks ===')
unhandled = []
for cb in sorted(settings_cbs):
    matched = False
    if cb in handled_exact:
        matched = True
    else:
        for p in handled_prefixes:
            if cb.startswith(p):
                matched = True
                break
    if not matched:
        unhandled.append(cb)
        print(f'  ❌ {cb}')

if not unhandled:
    print('  (none — all callbacks are handled)')
"

