cd /root/nanobot-src && python -c "
import ast, sys, os

issues = []
for root, dirs, files in os.walk('nanobot/groupchat'):
    dirs[:] = [d for d in dirs if d != '__pycache__']
    for f in files:
        if not f.endswith('.py'): continue
        path = os.path.join(root, f)
        try:
            with open(path) as fh:
                tree = ast.parse(fh.read(), path)
        except SyntaxError as e:
            issues.append(f'{path}: SyntaxError {e}')
            continue
        for node in ast.walk(tree):
            if isinstance(node, ast.ExceptHandler):
                if node.type is None:
                    issues.append(f'{path}:{node.lineno}: bare except')
                elif isinstance(node.type, ast.Name) and node.type.id == 'Exception' and node.body and len(node.body) == 1 and isinstance(node.body[0], ast.Pass):
                    issues.append(f'{path}:{node.lineno}: except Exception: pass (swallowed)')

for i in issues:
    print(i)
print(f'\\nTotal: {len(issues)}')
"

